      next: "নতুন লগইন পেলে কর্মী প্রথমবার অস্থায়ী পাসওয়ার্ড দিয়ে ঢুকে নিজের পাসওয়ার্ড ঠিক করেন। শর্তাবলি প্রকাশ করা থাকলে প্রথমে সেটি পড়ে রাজি হতে হয়, তারপর My HR খোলে। রোল বা অনুমতি বদল পরের পাতা খোলার সময় থেকেই কাজ করে, আর প্রতিটি বদল কার্যকলাপের লগে থাকে।",
