      what: "“Payroll” ট্যাবে মাস ধরে বেতনের তালিকা: মাস, অবস্থা, কতজন কর্মী, মোট বেতন, হাতে পাওয়া মোট আর কত দেওয়া বাকি। ওপরে টাকা দেখানো বা লুকানোর বোতাম আর “Prepare a payroll”। একটি মাস খুললে তার পাতা: ওপরে কাজের বোতাম, অপেক্ষার ওভারটাইম বা দাবির নোট, চারটি মোট (“Gross pay”, “Deductions”, “Take home”, “Still to pay”), তারপর “Employees” অংশে প্রত্যেকের সারি: দিন, বেতন, বাড়তি, কর্তন, হাতে পাওয়া, আর খসড়ায় “Change” বোতাম। নিচে বেতন দেওয়ার তালিকা আর খাতার তথ্য। এই নির্দেশিকা খসড়া বানানো ও ঠিক করা নিয়ে।",
      why: "হাতে বানানো বেতনের শিটে অনুপস্থিতি, অগ্রিমের কিস্তি আর ওভারটাইম মেলাতে দিন চলে যায়, ভুলও হয়। ধরুন অক্টোবরে 22 জন কর্মী। আপনি “Prepare” চাপলেন, অ্যাপ হাজিরা থেকে একজনের 2 দিন অনুপস্থিতি কাটল, আরেকজনের অগ্রিমের মাসিক 3,000 টাকা কিস্তি কাটল, অনুমোদিত ওভারটাইম ও দাবি যোগ করল। ঈদের মাস, তাই “Add a bonus” দিয়ে সবার মূল বেতনের 50% বোনাস দিলেন। একজন অফিসের ক্যালকুলেটর ভেঙেছেন, তাঁর সারিতে 500 টাকা কর্তন আর কারণ লিখলেন। এবার শুধু অনুমোদনের অপেক্ষা।",
